with filtered as (select id, order_id, method, amount, paid_at, status, length(status) as status_length, coalesce(method, 'UNKNOWN') as resolved_method from payments where paid_at >= timestamp '2024-03-16 02:00:00' and method is not null), prev_events as (select *, lag(paid_at) over (partition by status order by paid_at, id) as prev_paid_at from filtered), with_gaps as (select *, case when prev_paid_at is null or paid_at > prev_paid_at + interval 30 days then 1 else 0 end as is_new_session from prev_events), islands as (select *, sum(is_new_session) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as island_id from with_gaps) select method, count(case when method = 'bank_transfer' then 1 end) as bank_transfer_count, sum(case when status = 'FAILED' then status_length else 0 end) as failed_status_length, round(sum(is_new_session) / nullif(count(case when status = 'FAILED' then 1 end), 0), 2) as is_new_session_per_failed, count_if(status = 'SUCCESS') as success_events from islands group by method order by is_new_session_per_failed;
